from ute_ue.lteue import LteUe
from ute_ue.voice_call import VoiceCall
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer


class VoiceCall(VoiceCall):
    def __int__(self, vc):
        self.__vc = vc

    def await_voice_call_finish(self):
        """
        Waits until ongoing voice call is finished.
        """
        return self.__vc.await_voice_call_finish()

    def hold(self):
        """
        Hold active voice call
        :return:
        """
        return self.__vc.hold()

    def retrieve(self):
        """
        Retrieve held voice call
        :return:
        """
        return self.__vc.retrieve()

    def answer(self, with_video: bool = False):
        """
        Perform answer incoming voice call on UE PC.
        :type with_video:
        :return:
        """
        return self.__vc.answer(with_video)

    def drop(self):
        """
        Drop incoming voice call
        :return:
        """
        return self.__vc.drop()

    def get_state(self):
        """
        Returns voice_call actual state.
        :return str: voice_call state
        """
        return self.__vc.get_state()

    def __getattr__(self, item):
        attr = getattr(self.__vc, item)
        return attr


class DataTransfer(LteDataTransfer):
    def __int__(self, dt):
        self.__dt = dt

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        return self.__dt.start()

    def stop(self, should_raise: bool = True):
        """
        Stops already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :param should_raise: Allow to raise an exception or rather to log warning
        :return: None
        """
        return self.__dt.stop(should_raise)

    def await_finish(self):
        """
        Waits until this data transfer finish.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        :raises: :py:class:`ute_ue.exceptions.DataTransferCantWaitForeverException`: If this DT has 'forever' duration
        """
        return self.__dt.await_finish()

    def is_running(self):
        """
        Checks if both client and server are running:
        App Server: checks if paramiko connection has command exit status
        UE: checks if data transfer on UEPC is in active state
        Check is skipped if data transfer earlier was stopped, False is returned immediately
        :return: boolean
        """
        return self.__dt.is_running()

    def check_data_transfer(self):
        """Check if data transfer client and server output is progressing"""
        return self.__dt.check_data_transfer()

    def get_average_throughput(self, **kwargs):
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or
        from 'dt.start()' to 'dt.stop()' if data transfer is already finished or
        with currently available iperf intervals that were already transferred.

        :param omit: it is a delay in seconds to start counting the throughput
                     ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the throughput
                    ex. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :return: value of Average throughput in unit: Kbits/sec
        """
        return self.__dt.get_average_throughput(**kwargs)

    def release_data_transfer(self):
        """Releases resources on remote UE PC."""
        return self.__dt.release_data_transfer()

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        return self.__dt.get_datagram_loss()

    def get_client_report_rows(self):
        """
        Returns client iperf report received after stop data transfer, or empty list.
        :return: List[IperfServerReportRow]
        """
        return self.__dt.get_client_report_rows()

    def __getattr__(self, item):
        attr = getattr(self.__dt, item)
        return attr


class Ue(LteUe):
    def __init__(self, ue):
        self.__ue = ue

    def create_data_transfer(self, name: str, **kwargs) -> DataTransfer:
        """
        Create Data Transfer instance for Iphone UE.

        :param name: str: Data Transfer Alias name
        :return: Instance of data transfer
        """
        return self.__ue.create_data_transfer(name, **kwargs)

    def create_voice_call(self, name: str, **kwargs) -> VoiceCall:
        """
        Create Voice Call instance for Android UE.

        Optional argument is `to` for other UE alias or str representation of call number.

        :param name: str: Voice Call Alias
        :return: Instance of voice call
        """
        return self.__ue.create_voice_call(name, **kwargs)

    def attach(self, timeout=-1, validation=True, top_cmd_only=False, **kwargs):
        """
        Perform attach on UE.

        :param timeout: not supported
        :param validation: if True, check if detach state was changed successfully
                              and raise an exception if not; turned on by default
        :param top_cmd_only: not supported
        :return: None
        """
        return self.__ue.attach(timeout=timeout, validation=validation, top_cmd_only=top_cmd_only, **kwargs)

    def detach(self, timeout=-1, validation=True, top_cmd_only=False, **kwargs):
        """
        Perform detach on UE.
        No action if UE is already detached.

        :param timeout: not supported
        :param validation: if True, check if detach state was changed successfully
                              and raise an exception if not; turned on by default
        :param top_cmd_only: not supported
        :return: None
        """
        return self.__ue.detach(timeout=timeout, validation=validation, top_cmd_only=top_cmd_only, **kwargs)

    def prepare_ue(self):
        """Call this after constructor. This method may take some time."""
        return self.__ue.prepare_ue()

    def get_ue_info(self, info: str):
        """
        Returns specified UE information, which can be assigned to Robot variable.
        :param infos_list: info(s) to be returned, 'ALL' by default.
        """
        return self.__ue.get_ue_info(info)

    def reboot_ue(self, timeout: int = 120):
        """
        Reboot Android ue and wait until it boots
        :param timeout - waiting time in seconds for android ue after reboot
        """
        return self.__ue.reboot_ue(timeout)

    def enable_mobile_data(self):
        """
        Enable mobile data
        :return: None
        """
        return self.__ue.enable_mobile_data()

    def disable_mobile_data(self):
        """
        Disable mobile data
        :return: None
        """
        return self.__ue.disable_mobile_data()

    def get_apn(self, pdp: int = 0):
        """
        Get apn name for pdp context.

        :return:
        """
        return self.__ue.get_apn(pdp)

    def set_apn(self, apn_name: str, pdp: int = 0):
        """
        Set apn name for pdp context.

        :return:
        """
        return self.__ue.set_apn(apn_name, pdp)

    def set_fake_primary_dns(self, dns: str):
        """
        Set Fake Primary DNS Key

        :param str dns: (String) Should be IP address of the DNS
        :returns: None
        """
        return self.__ue.set_fake_primary_dns(dns)

    def get_fake_dns_addresses(self, pdp: int):
        """
        Get Fake DNS Keys

        :param pdp: The PDP ID
        :type pdp: Int
        :returns: None
        """
        return self.__ue.get_fake_dns_addresses(pdp)

    def activate_data_pdp_context(self, pdp: int = 0):
        """
        Activate selected PDP context

        :param pdp: The PDP ID
        :type pdp: Int
        :returns: None
        """
        return self.__ue.activate_data_pdp_context(pdp)

    def deactivate_data_pdp_context(self, pdp: int = 0):
        """
        Activate selected PDP context

        :param pdp: The PDP ID
        :type pdp: Int
        :returns: None
        """
        return self.__ue.deactivate_data_pdp_context(pdp)

    def get_rat(self):
        """
        Get RAT on the device.

        :returns: String
        """
        return self.__ue.get_rat()

    def set_rat(self, rat_selection: str):
        """
        Set RAT on the device.

        :returns: String
        """
        return self.__ue.set_rat(rat_selection)

    def get_active_and_supported_bands(self, identifier: int = 1):
        """
        Returns the active and supported bands.

        :param identifier: SIM Slot identifier. Valid values are 1 and 2.
        :type identifier: int
        :returns: dict
        """
        return self.__ue.get_active_and_supported_bands(identifier)

    def set_active_bands(self, *args, **kawrgs):
        """
        Set active bands.

        :param technology:
        :type technology: String
        :param bands:
        :type bands: dict
        :param identifier: SIM Slot identifier. Valid values are 1 and 2.
        :type identifier: int
        :returns: None
        """
        return self.__ue.set_active_bands(*args, **kawrgs)

    def get_all_capabilities(self):
        """
        Returns a Capabilities instance containing the print the device supports.

        :returns: Returns capabilities of the device.
        :rtype: None
        """
        return self.__ue.get_all_capabilities()
